### Ran Playwright code
```js
await (async(page)=>{
await page.reload();await page.getByText('7 of 7 contacts').waitFor();
if(await page.getByRole('button',{name:/Zoë Verifier/}).count())throw Error('Deleted record resurrected');
await page.getByRole('button',{name:/Persistence Fixture/}).filter({visible:true}).click();
if(await page.getByLabel('Notes',{exact:true}).inputValue()!=='Created and edited by browser; survives actual server restart.')throw Error('Lost persisted edit');
await page.getByRole('button',{name:'Cancel',exact:true}).click();
await page.getByRole('button',{name:/Dev Patel/}).filter({visible:true}).click();
if(await page.getByLabel('Notes',{exact:true}).inputValue()!=='Unsaved fictional retry note')throw Error('Lost retry save');
return {restart:'PASS',createdEdited:'Persistence Fixture notes retained',deleted:'Zoë Verifier remains absent',others:'Six seed contacts preserved',theme:await page.locator('html').getAttribute('class')};
})(page);
```
